import { auth } from "@orksys-survey/auth";
import { NextResponse } from "next/server";

import type { NextRequest } from "next/server";

const publicRoutes = ["/", "/login", "/onboarding", "/success"];
const apiRoutes = ["/api"];

export async function middleware(request: NextRequest) {
	const { pathname } = request.nextUrl;

	// Allow public routes
	if (publicRoutes.some((route) => pathname === route || pathname.startsWith(route + "/"))) {
		// For onboarding page, check if user already has active org
		if (pathname === "/onboarding") {
			const session = await auth.api.getSession({
				headers: request.headers,
			});

			if (!session?.user) {
				return NextResponse.redirect(new URL("/login", request.url));
			}

			if (session.session.activeOrganizationId) {
				return NextResponse.redirect(new URL("/dashboard", request.url));
			}
		}

		return NextResponse.next();
	}

	// Allow API routes
	if (apiRoutes.some((route) => pathname.startsWith(route))) {
		return NextResponse.next();
	}

	// Protected routes - check authentication
	const session = await auth.api.getSession({
		headers: request.headers,
	});

	if (!session?.user) {
		return NextResponse.redirect(new URL("/login", request.url));
	}

	// Check for active organization
	if (!session.session.activeOrganizationId) {
		return NextResponse.redirect(new URL("/onboarding", request.url));
	}

	return NextResponse.next();
}

export const config = {
	matcher: [
		/*
		 * Match all request paths except for the ones starting with:
		 * - _next/static (static files)
		 * - _next/image (image optimization files)
		 * - favicon.ico (favicon file)
		 */
		"/((?!_next/static|_next/image|favicon.ico).*)",
	],
};

import { auth } from "@orksys-survey/auth";
import { headers } from "next/headers";
import { redirect } from "next/navigation";

import CreateOrganizationForm from "@/components/onboarding/create-organization-form";
import SelectOrganization from "@/components/onboarding/select-organization";

export default async function OnboardingPage() {
	const session = await auth.api.getSession({
		headers: await headers(),
	});

	if (!session?.user) {
		redirect("/login");
	}

	if (session.session.activeOrganizationId) {
		redirect("/dashboard");
	}

	// Fetch user's organizations to determine which view to show
	const organizations = await auth.api.organization.list({
		headers: await headers(),
	});

	const hasOrganizations = organizations && organizations.length > 0;

	return (
		<div className="mx-auto mt-10 w-full max-w-md p-6">
			<h1 className="mb-6 text-center font-bold text-3xl">
				{hasOrganizations ? "Select Organization" : "Create Organization"}
			</h1>
			<p className="mb-6 text-center text-muted-foreground">
				{hasOrganizations
					? "Choose an organization to continue"
					: "Create your first organization to get started"}
			</p>

			{hasOrganizations ? (
				<SelectOrganization organizations={organizations} />
			) : (
				<CreateOrganizationForm />
			)}
		</div>
	);
}

"use client";

import { useForm } from "@tanstack/react-form";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import z from "zod";

import { authClient } from "@/lib/auth-client";

import { Button } from "../ui/button";
import { Input } from "../ui/input";
import { Label } from "../ui/label";

export default function CreateOrganizationForm() {
	const router = useRouter();

	const form = useForm({
		defaultValues: {
			name: "",
			slug: "",
		},
		onSubmit: async ({ value }) => {
			try {
				const result = await authClient.organization.create({
					name: value.name,
					slug: value.slug,
				});

				if (result.error) {
					toast.error(result.error.message || "Failed to create organization");
					return;
				}

				// Set the newly created organization as active
				if (result.data?.id) {
					await authClient.organization.setActive({
						organizationId: result.data.id,
					});
				}

				toast.success("Organization created successfully");
				router.push("/dashboard");
				router.refresh();
			} catch (error) {
				toast.error("An unexpected error occurred");
			}
		},
		validators: {
			onSubmit: z.object({
				name: z.string().min(2, "Name must be at least 2 characters"),
				slug: z
					.string()
					.min(2, "Slug must be at least 2 characters")
					.max(50, "Slug must be at most 50 characters")
					.regex(/^[a-z0-9-]+$/, "Slug can only contain lowercase letters, numbers, and hyphens"),
			}),
		},
	});

	// Auto-generate slug from name
	const generateSlug = (name: string) => {
		return name
			.toLowerCase()
			.replace(/[^a-z0-9]+/g, "-")
			.replace(/^-|-$/g, "");
	};

	return (
		<form
			onSubmit={(e) => {
				e.preventDefault();
				e.stopPropagation();
				form.handleSubmit();
			}}
			className="space-y-4"
		>
			<div>
				<form.Field name="name">
					{(field) => (
						<div className="space-y-2">
							<Label htmlFor={field.name}>Organization Name</Label>
							<Input
								id={field.name}
								name={field.name}
								value={field.state.value}
								onBlur={field.handleBlur}
								onChange={(e) => {
									field.handleChange(e.target.value);
									// Auto-generate slug if empty
									const slugField = field.form.getFieldValue("slug");
									if (!slugField) {
										field.form.setFieldValue("slug", generateSlug(e.target.value));
									}
								}}
								placeholder="My Organization"
							/>
							{field.state.meta.errors.map((error) => (
								<p key={error?.message} className="text-red-500 text-sm">
									{error?.message}
								</p>
							))}
						</div>
					)}
				</form.Field>
			</div>

			<div>
				<form.Field name="slug">
					{(field) => (
						<div className="space-y-2">
							<Label htmlFor={field.name}>Slug</Label>
							<Input
								id={field.name}
								name={field.name}
								value={field.state.value}
								onBlur={field.handleBlur}
								onChange={(e) => field.handleChange(e.target.value)}
								placeholder="my-organization"
							/>
							<p className="text-muted-foreground text-sm">
								Used in URLs and identifiers
							</p>
							{field.state.meta.errors.map((error) => (
								<p key={error?.message} className="text-red-500 text-sm">
									{error?.message}
								</p>
							))}
						</div>
					)}
				</form.Field>
			</div>

			<form.Subscribe>
				{(state) => (
					<Button
						type="submit"
						className="w-full"
						disabled={!state.canSubmit || state.isSubmitting}
					>
						{state.isSubmitting ? "Creating..." : "Create Organization"}
					</Button>
				)}
			</form.Subscribe>
		</form>
	);
}

"use client";

import { useRouter } from "next/navigation";
import { toast } from "sonner";

import { authClient } from "@/lib/auth-client";

import { Button } from "../ui/button";

interface Organization {
	id: string;
	name: string;
	slug: string;
}

interface SelectOrganizationProps {
	organizations: Organization[];
}

export default function SelectOrganization({ organizations }: SelectOrganizationProps) {
	const router = useRouter();

	const handleSelectOrganization = async (organizationId: string) => {
		try {
			const result = await authClient.organization.setActive({
				organizationId,
			});

			if (result.error) {
				toast.error(result.error.message || "Failed to set active organization");
				return;
			}

			toast.success("Organization selected");
			router.push("/dashboard");
			router.refresh();
		} catch (error) {
			toast.error("An unexpected error occurred");
		}
	};

	return (
		<div className="space-y-2">
			{organizations.map((org) => (
				<Button
					key={org.id}
					variant="outline"
					className="w-full justify-start"
					onClick={() => handleSelectOrganization(org.id)}
				>
					<span className="font-medium">{org.name}</span>
					<span className="ml-2 text-muted-foreground text-sm">({org.slug})</span>
				</Button>
			))}
		</div>
	);
}

"use client";

import { Building2, Check, ChevronsUpDown } from "lucide-react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";

import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuLabel,
	DropdownMenuSeparator,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { authClient } from "@/lib/auth-client";

import { Button } from "./ui/button";
import { Skeleton } from "./ui/skeleton";

export default function OrganizationSwitcher() {
	const router = useRouter();
	const { data: session, isPending: isSessionPending } = authClient.useSession();
	const { data: organizations, isPending: isOrgsPending } = authClient.organization.list();

	const isPending = isSessionPending || isOrgsPending;

	if (isPending) {
		return <Skeleton className="h-9 w-40" />;
	}

	if (!session || !organizations || organizations.length === 0) {
		return null;
	}

	const currentOrg = organizations.find((org) => org.id === session.session.activeOrganizationId);

	const handleSwitchOrganization = async (organizationId: string) => {
		try {
			const result = await authClient.organization.setActive({
				organizationId,
			});

			if (result.error) {
				toast.error(result.error.message || "Failed to switch organization");
				return;
			}

			router.refresh();
		} catch (error) {
			toast.error("An unexpected error occurred");
		}
	};

	return (
		<DropdownMenu>
			<DropdownMenuTrigger render={<Button variant="outline" className="gap-2" />}>
				<Building2 className="h-4 w-4" />
				<span className="truncate max-w-32">{currentOrg?.name || "Select org"}</span>
				<ChevronsUpDown className="h-4 w-4 opacity-50" />
			</DropdownMenuTrigger>
			<DropdownMenuContent className="bg-card w-56">
				<DropdownMenuLabel>Organizations</DropdownMenuLabel>
				<DropdownMenuSeparator />
				{organizations.map((org) => (
					<DropdownMenuItem
						key={org.id}
						onClick={() => handleSwitchOrganization(org.id)}
						className="justify-between"
					>
						<span className="truncate">{org.name}</span>
						{org.id === session.session.activeOrganizationId && (
							<Check className="h-4 w-4" />
						)}
					</DropdownMenuItem>
				))}
			</DropdownMenuContent>
		</DropdownMenu>
	);
}

